sections.code:
fn add_exclamation(text: &mut String) {
    text.push_str("!");
}

fn main() {
    let mut message = String::from("Hello");
    add_exclamation(&mut message);
    add_exclamation(&mut message);
    println!("{message}");
}

fn main() {
    let mut score = 10;
    let r = &mut score;
    *r += 5;              // * dereferences: it follows the reference to the value
    // let r2 = &score;   // error while r is still in use
    println!("{r}");
    let r2 = &score;      // fine: r isn't used any more
    println!("{r2}");
}

